            mv.visitFieldInsn(PUTSTATIC, packageAndClassName, site.field, site.desc);
            mv.visitLabel(done);
            mv.visitFieldInsn(GETSTATIC, packageAndClassName, site.field, site.desc);
            methodReturnAndFinish();
        }
    } finally {
        mv = savedMv;
    }
}

